/**
 * M16.3.1 — per-row VAT-treatment override (the export-sale case, or
 * correcting an assumed default). Setting a non-'S' value clears the
 * row's VAT (Z/E/O rows carry zero VAT and say why); setting 'S' on a
 * row with no VAT extracts it from the gross amount at 15%. null
 * returns the row to honest-unknown.
 * @nullable
 */
export type TransactionUpdateTaxTreatment = typeof TransactionUpdateTaxTreatment[keyof typeof TransactionUpdateTaxTreatment] | null;


export const TransactionUpdateTaxTreatment = {
  S: 'S',
  Z: 'Z',
  E: 'E',
  O: 'O',
} as const;

/**
 * Flaw #6 — the human's answer to "did this payment actually carry
 * VAT?". Anything other than `charged` clears the row's VAT; setting
 * `charged` on a standard-rated row re-extracts it from the gross.
 * @nullable
 */
export type TransactionUpdateVatBasis = typeof TransactionUpdateVatBasis[keyof typeof TransactionUpdateVatBasis] | null;


export const TransactionUpdateVatBasis = {
  charged: 'charged',
  reverse_charge: 'reverse_charge',
  supplier_unregistered: 'supplier_unregistered',
} as const;

/**
 * B5 — where a transfer went. `own_account` = between accounts of this
 * business (business cash unchanged, so the ledger is right to be
 * silent); `external` = it left the business (cash fell, and the
 * ledger is understating it). `null` means NOT DECLARED — never
 * "external". Only a transfer may carry it.
 * @nullable
 */
export type TransactionUpdateTransferDirection = typeof TransactionUpdateTransferDirection[keyof typeof TransactionUpdateTransferDirection] | null;


export const TransactionUpdateTransferDirection = {
  own_account: 'own_account',
  external: 'external',
} as const;

